def controler(zones, matrice, essais):
    lignes = []
    for src, dst in essais:
        zs, zd = zone_de(src, zones), zone_de(dst, zones)
        ok = "inconnue" not in (zs, zd) and flux_autorise(matrice, zs, zd)
        lignes.append(src + " (" + zs + ") -> " + dst + " (" + zd + ") : " + ("autorisé" if ok else "bloqué"))
