    for machine, (ip, prefixe, passerelle) in releves["configs"].items():
        resultat = diagnostic(ip, prefixe, passerelle)
        if resultat != "ok":
            constats.append(["critique", machine + " : " + resultat])
    for machine, mesures in releves["pings"].items():
        verdict = qualite(mesures)
        if verdict == "coupée":
            constats.append(["critique", machine + " : connexion coupée"])
        elif verdict == "mauvaise":
            constats.append(["moyen", machine + " : connexion mauvaise"])
    for machine, ports in releves["ports"].items():
        for port in sorted(ports):
            if port in RISQUES:
                constats.append(["élevé", machine + " : " + str(port) + " (" + RISQUES[port] + ")"])
